// 已装插件：只读清单（装了什么、从哪装的、启用没启用）；不装不卸、不联网
function InstalledPlugins() {
	const [data, setData] = react.useState(null);
	const [error, setError] = react.useState(null);
	const [busy, setBusy] = react.useState(false);
	const load = react.useCallback(async () => {
		setBusy(true);
		const r = await api("GET", "/plugins/installed");
		setBusy(false);
		if (r?.ok) { setData(r); setError(null); } else setError(r?.error ?? "插件清单读不出来");
	}, []);
	react.useEffect(() => { load(); }, [load]);
	if (!data) return error ? h("div", { className: "fs-notice", role: "alert" }, h("b", null, "插件清单加载失败"), h("span", null, error), Button({ variant: "secondary", onClick: load }, "重试")) : h("div", { className: "fs-empty" }, Dot("ongoing"));
	const KIND = { official: "官方", third: "社区", local: "本地" };
	const plugins = Array.isArray(data.plugins) ? data.plugins : [];
	return Group({ title: "已装插件", aside: h("span", { className: "fs-group-aside" }, `${plugins.length} 个 · 启用 ${data.enabled ?? 0} 个`, Button({ variant: "ghost", onClick: load, disabled: busy }, busy ? "读取中…" : "刷新")) },
		h("div", { className: "fs-list" }, plugins.map((x) => h("div", { className: "fs-item", key: x.name },
			h("span", { className: cx("fs-item-main", x.enabled === false && "fs-muted") }, x.name),
			h("span", { className: "fs-item-meta" },
				x.self ? Tag("本插件", "outline") : null,
				Tag(`${KIND[x.kind] ?? "其他"}${x.version ? ` ${x.version}` : ""}`, x.enabled ? "success" : "outline"),
				x.enabled ? null : Tag("未启用", "outline", { title: "装在依赖里，但没列进 profile 的 bundles，宿主不会加载" }))))),
		h("p", { className: "fs-row-meta" }, `profile：${data.profile ?? ""} · 只读清单；要装要卸走 dshmarket`));
}
